-- ============================================================
-- Notícias no painel.
-- 1. Cidade e coordenadas (opcionais) para posicionar o pino no globo, como as notícias em Markdown tinham.
-- 2. Traz para o banco as 8 notícias que estavam em src/content/noticias, já publicadas,
--    para que possam ser editadas ou tiradas do ar pelo painel. Não duplica se o link já existir.
-- ============================================================

-- AlterTable
ALTER TABLE "noticias" ADD COLUMN "local" TEXT,
ADD COLUMN "lat" DOUBLE PRECISION,
ADD COLUMN "lng" DOUBLE PRECISION;

ALTER TABLE "noticias"
  ADD CONSTRAINT "noticias_local_check" CHECK ("local" IS NULL OR char_length("local") BETWEEN 2 AND 80),
  ADD CONSTRAINT "noticias_lat_check" CHECK ("lat" IS NULL OR "lat" BETWEEN -90 AND 90),
  ADD CONSTRAINT "noticias_lng_check" CHECK ("lng" IS NULL OR "lng" BETWEEN -180 AND 180);

-- Notícias trazidas do Markdown
INSERT INTO "noticias" ("semana", "status", "titulo", "resumo", "por_que_importa", "categoria", "continente", "local", "lat", "lng", "fonte", "link", "data_fonte", "titulo_original", "motivo", "revisado_em", "publicado_em") VALUES
  (date_trunc('week', DATE '2026-10-15')::date, 'aprovada', 'Startups africanas captam US$ 2,49 bilhões em nove meses, puxadas por um terceiro trimestre forte', 'O volume captado subiu 7,8% sobre 2025, mesmo com menos rodadas. Nigéria e Egito lideram, e energia, fintech e mobilidade concentraram os maiores aportes do trimestre.', 'Menos rodadas e cheques maiores mostram o capital indo para negócios com receita e infraestrutura. A África é um mercado emergente parecido com o nosso e serve de referência para quem busca investimento.', 'negocios', 'africa', 'Lagos, Nigéria', 6.5244, 3.3792, 'TechCabal', 'https://techcabal.com/2026/10/15/african-startups-raise-2-49b-in-9-months/', DATE '2026-10-15', 'Startups africanas captam US$ 2,49 bilhões em nove meses, puxadas por um terceiro trimestre forte', 'Notícia escrita à mão, trazida de src/content/noticias para o painel.', '2026-10-15 12:00:00-03', '2026-10-15 12:00:00-03'),
  (date_trunc('week', DATE '2026-10-20')::date, 'aprovada', 'Alemanha fecha parceria com a Nvidia e pede que médias empresas usem seus dados com IA', 'Em cúpula de investimentos em Berlim, o governo alemão assinou acordo com a Nvidia para IA industrial. A Siemens apresentou ferramentas que reduzem em até 85% a engenharia de preparação da produção.', 'O recado do chanceler às pequenas e médias empresas foi aproveitar os dados que elas já têm. Isso vale também para indústrias brasileiras, onde o histórico de produção costuma ficar parado.', 'solucoes', 'europa', 'Berlim, Alemanha', 52.52, 13.405, 'CNBC', 'https://www.cnbc.com/2026/10/20/german-chancellor-urges-businesses-to-embrace-ai.html', DATE '2026-10-20', 'Alemanha fecha parceria com a Nvidia e pede que médias empresas usem seus dados com IA', 'Notícia escrita à mão, trazida de src/content/noticias para o painel.', '2026-10-20 12:00:00-03', '2026-10-20 12:00:00-03'),
  (date_trunc('week', DATE '2026-10-08')::date, 'aprovada', 'Austrália quer exigir que empresas de IA provem que seus sistemas de segurança funcionam', 'O governo australiano prepara padrões nacionais até o fim de 2026 e uma lei em 2027. Desenvolvedores de IA avançada terão de testar riscos continuamente, num modelo inspirado em bancos e aviação.', 'A tendência é cobrar de quem fornece IA a comprovação de testes e a notificação de incidentes. Empresas brasileiras que usam ou revendem essas ferramentas devem esperar mais exigências contratuais de governança.', 'negocios', 'oceania', 'Sydney, Austrália', -33.8688, 151.2093, 'ABC News (Austrália)', 'https://www.abc.net.au/news/2026-10-08/federal-politics-ai-regulation-andrew-charlton-speech/107241674', DATE '2026-10-08', 'Austrália quer exigir que empresas de IA provem que seus sistemas de segurança funcionam', 'Notícia escrita à mão, trazida de src/content/noticias para o painel.', '2026-10-08 12:00:00-03', '2026-10-08 12:00:00-03'),
  (date_trunc('week', DATE '2026-10-23')::date, 'aprovada', 'Goldman Sachs destina US$ 500 milhões para treinar pequenos negócios em IA com Anthropic, Google, Meta e OpenAI', 'O banco criou um instituto de IA para pequenas empresas. Na pesquisa que acompanha o anúncio, 86% dos empresários já usam IA, mas só 15% a integraram de fato à operação.', 'Os dados mostram que o gargalo está em treinar pessoas e integrar a IA aos processos, não em ter o modelo mais avançado. A maioria gasta menos de US$ 100 por mês e não reduziu equipe.', 'gestao', 'america-do-norte', 'Nova York, EUA', 40.7128, -74.006, 'Fortune', 'https://fortune.com/2026/10/23/david-solomon-frontier-models-not-needed-small-business/', DATE '2026-10-23', 'Goldman Sachs destina US$ 500 milhões para treinar pequenos negócios em IA com Anthropic, Google, Meta e OpenAI', 'Notícia escrita à mão, trazida de src/content/noticias para o painel.', '2026-10-23 12:00:00-03', '2026-10-23 12:00:00-03'),
  (date_trunc('week', DATE '2026-10-20')::date, 'aprovada', 'Google lança no Gemini um painel para pequenos negócios cuidarem de marketing, marca e finanças', 'Anunciado na Feira do Empreendedor do Sebrae-SP, o novo espaço do Gemini cria peças com a identidade da marca e monta relatórios de caixa a partir de notas, planilhas e recibos.', 'Tarefas que antes pediam agência ou analista financeiro passam a caber numa ferramenta de uso geral. Mas a qualidade depende de dados organizados, e quem não arrumar a casa terá pouco ganho.', 'solucoes', 'america-do-sul', 'São Paulo, Brasil', -23.5505, -46.6333, 'Exame', 'https://exame.com/inteligencia-artificial/do-anuncio-ao-fluxo-de-caixa-google-amplia-gemini-para-pequenas-e-medias-empresas/', DATE '2026-10-20', 'Google lança no Gemini um painel para pequenos negócios cuidarem de marketing, marca e finanças', 'Notícia escrita à mão, trazida de src/content/noticias para o painel.', '2026-10-20 12:00:00-03', '2026-10-20 12:00:00-03'),
  (date_trunc('week', DATE '2026-10-01')::date, 'aprovada', 'Pernambuco abre R$ 4,5 milhões em editais para startups e soluções ao governo estadual', 'No Porto Digital, o governo de PE lançou dois editais: R$ 1,5 mi para tirar startups da ideia ao produto e R$ 3 mi para pequenas empresas de tecnologia resolverem desafios do Estado.', 'O setor público vira cliente de pequenas empresas de tecnologia locais. É um caminho de receita e validação para quem constrói produto em Pernambuco. Os resultados saem em novembro e os projetos começam em dezembro.', 'negocios', 'america-do-sul', 'Recife, Brasil', -8.0631, -34.8711, 'Revista Algomais', 'https://algomais.com/pernambuco-lanca-r-45-milhoes-em-editais-para-startups-e-solucoes-para-o-setor-publico/', DATE '2026-10-01', 'Pernambuco abre R$ 4,5 milhões em editais para startups e soluções ao governo estadual', 'Notícia escrita à mão, trazida de src/content/noticias para o painel.', '2026-10-01 12:00:00-03', '2026-10-01 12:00:00-03'),
  (date_trunc('week', DATE '2026-10-26')::date, 'aprovada', 'Pequenas empresas têm até 30/10 para decidir como vão recolher IBS e CBS em 2027', 'Optantes do Simples podem escolher recolher os novos tributos da reforma pelo regime regular. A escolha vale a partir de janeiro de 2027, e a NFS-e nacional passa a ser obrigatória em 1º/11.', 'A escolha mexe com preço, créditos tributários, relação com clientes PJ e fluxo de caixa. Vale simular os dois cenários com o contador e revisar o sistema de emissão de notas antes do prazo.', 'gestao', 'america-do-sul', 'Brasília, Brasil', -15.7939, -47.8828, 'Agência Brasil', 'https://agenciabrasil.ebc.com.br/economia/noticia/2026-10/prazo-para-empresas-escolherem-modelo-do-simples-acaba-nesta-sexta', DATE '2026-10-26', 'Pequenas empresas têm até 30/10 para decidir como vão recolher IBS e CBS em 2027', 'Notícia escrita à mão, trazida de src/content/noticias para o painel.', '2026-10-26 12:00:00-03', '2026-10-26 12:00:00-03'),
  (date_trunc('week', DATE '2026-10-22')::date, 'aprovada', 'Sudeste Asiático adota IA em ritmo recorde, e o ganho aparece mais nas empresas que nas assinaturas', 'O relatório e-Conomy SEA aponta 243 milhões de usuários de IA generativa na região, mas só 1% a 2% pagam assinatura. O retorno aparece em conversão de vendas, atendimento e publicidade.', 'O caso da Shopee, que atende cerca de 80% das dúvidas com chatbots e cortou 30% do custo por contato, mostra onde a IA costuma se pagar primeiro: atendimento e vendas digitais.', 'negocios', 'asia', 'Singapura', 1.3521, 103.8198, 'CNBC', 'https://www.cnbc.com/2026/10/22/southeasaisa-singapore-bain-temasek-google-.html', DATE '2026-10-22', 'Sudeste Asiático adota IA em ritmo recorde, e o ganho aparece mais nas empresas que nas assinaturas', 'Notícia escrita à mão, trazida de src/content/noticias para o painel.', '2026-10-22 12:00:00-03', '2026-10-22 12:00:00-03')
ON CONFLICT ("link") DO NOTHING;
